{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret har væsentlige fejl og mangler. Det nævner slet ikke vejledningens udgangspunkt om omkring et års symptomer/følger før ansøgningen, og det omtaler ikke muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed (SU-bek. § 36, stk. 2). Det hævder, at en midlertidig nedsættelse 'ikke opfylder varighedskravet', og at en tilstand, der 'først senere blev kronisk/varig', gør betingelsen 'ikke opfyldt'. Det strider mod rubrikken, hvor en ikke-varig tilstand kan vurderes varig efter omkring et år. Svaret bygger desuden på ikke-understøttede forarbejder og nævnspraksis."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Element 1 (varighed vedrører art og grad) er kun delvist dækket. Element 2 (hverken af sig selv eller ved behandling bedres væsentligt inden for en længere årrække) er dækket. Element 3 (omkring et år / mindst et års symptomer før ansøgning) mangler helt. Element 4 (tidsbegrænset tillæg ved sandsynliggjort varighed) mangler helt."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret behandler varighedsbegrebet, men besvarer ikke anden del af spørgsmålet korrekt. Om tilstande, der ikke er varige fra begyndelsen, siger det kun, at de som udgangspunkt ikke opfylder kravet, og at man kan søge igen. Det nævner ikke et-års-vurderingen, som er det centrale svar. Meget af teksten handler om generel nævnspraksis om midlertidig sygdom."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser med nummererede henvisninger til identificerbare kilder: SU-loven § 7, stk. 3, L 182, og tre afgørelser fra Ankenævnet. Der er dog en 'uden kilde'-markering i konklusionen."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Flere af de anførte kilder er ikke aktuelle eller i den frosne kildeafgrænsning. Det gælder forarbejder fra 2019 (L 182) og ældre nævnsafgørelser fra 2013, 2019 og 2023. Den aktuelle vejledning (VEJ 10157) og SU-bekendtgørelsen § 36-37 er ikke citeret. Svaret selv kalder kilderne 'uverificerede'."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande er ikke understøttet af de angivne kilder. Det gælder 'der kan søges igen på det nye grundlag' (kilde 5 findes ikke i kildelisten), 'praksis viser, at en lidelse kan være varig, selv om behandling pågår' og påstanden om, at midlertidig sygdom ikke kan begrunde varighed. Konklusionen er markeret 'uden kilde'. Lovteksten i § 7, stk. 3 understøtter ikke påstandene om prognose og om tidsforløb."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer regler uden støtte i materialet. Det hævder, at en tilstand, der 'først senere er blevet kronisk/varig', ikke opfylder betingelsen, men at der kan søges igen. Det gør 'prognose på ansøgningstidspunktet' til en regel. Det antyder også, at den studerende 'senere kan miste grundlaget' ved kronisk sygdom. Ingen af delene har støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Rubrikkens krævede forbehold mangler. Der er intet om 'omkring et år' som udgangspunkt, og intet om tidsbegrænset tillæg ved sandsynliggjort varighed. 'Som udgangspunkt' bevares kun ved den ene definition. Svaret afviser en midlertidig lidelse uden at nævne, at den kan vurderes varig efter omkring et år."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt modstridende. Det siger, at kronisk/langvarig sygdom falder uden for den 'midlertidige kategori' og dermed kan føre til afslag eller tab af støtte. Samtidig kræver det, at tilstanden er varig. Konklusionen siger, at betingelsen ikke er opfyldt, hvis tilstanden 'først senere er blevet kronisk/varig', hvilket bryder med den ellers fremstillede varighedslogik. Linjen 'der skal være støtte for, at tilstanden faktisk er varig' er uklar."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten er upræcis. Svaret gør 'ikke opfyldt' for midlertidige tilstande næsten absolut ('er betingelsen ikke opfyldt') i konklusionen. Det gengiver ikke vejledningens 'som udgangspunkt' og 'kan vurderes at være varig' om omkring et år. Det omtaler heller ikke, at tidsbegrænset tillæg 'kan' gives."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "yes",
      "reason": "Svaret fremhæver, at funktionsnedsættelsen skal være varig, og hvad varig betyder: ikke væsentlig bedring inden for en længere årrække."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret nævner hverken, at en ikke-varig funktionsnedsættelse kan vurderes varig efter omkring et år, eller at symptomer eller følger som udgangspunkt skal have været til stede i mindst et år før ansøgningen."
    }
  },
  "overall_notes": "Svaret rammer kernen i varighedsdefinitionen (ingen væsentlig bedring inden for en længere årrække, heller ikke ved behandling). Det udelader helt étårsudgangspunktet og muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed. Det erstatter dem med ikke-understøttede påstande om nævnspraksis og genansøgning. Det er markeret som et 'begrænset svar' med uverificerede kilder, og kilderne er ikke de aktuelle vejledninger eller bekendtgørelsesbestemmelser."
}

